import { useEditorSelector } from "platejs/react";

export interface UseFontSizeOptions {
  /**
   * Map of block type keys to their default font sizes (in px).
   * When the FontSizePlugin mark is not set, the hook returns the
   * value matching the current block type from this map.
   *
   * @example
   * { [H1Plugin.key]: 32, [H2Plugin.key]: 24, [H3Plugin.key]: 20 }
   */
  defaults?: Record<string, number | undefined>;
  /** Default font size when no mark is set and the block type isn't in `defaults`. */
  fallback: number | undefined;
  /** Optional editor ID when multiple editors exist under a `PlateController`. */
  editorId?: string;
}

/**
 * Subscribe to the active font size at the editor's selection.
 *
 * Reads the `fontSize` mark value first. If no mark is set, falls back
 * to the `defaults` map by block type, then to `fallback`.
 *
 * Must be used inside a `<RichText>` (or `<Plate>`) context.
 * Requires `@platejs/basic-styles` with `FontSizePlugin` configured.
 *
 * @example
 * const size = useFontSize({
 *   defaults: {
 *     [H1Plugin.key]: theme.resolveFontSize(theme.typography.heading.lg.fontSize),
 *     [H2Plugin.key]: theme.resolveFontSize(theme.typography.heading.md.fontSize),
 *   },
 *   fallback: theme.resolveFontSize(theme.typography.body.md.fontSize),
 * });
 */
export function useFontSize({ defaults, fallback, editorId }: UseFontSizeOptions): number {
  const resolvedFallback = fallback ?? 14;
  return useEditorSelector(
    (ed) => {
      if (!ed) return resolvedFallback;

      const marks = ed?.api?.marks?.() || ed?.marks;
      const size = marks?.fontSize as string | undefined;

      if (size) {
        const parsed = parseInt(size, 10);
        if (!isNaN(parsed)) return parsed;
      }

      if (defaults) {
        const blockType = ed?.api?.block()?.[0]?.type;
        if (blockType && blockType in defaults) {
          return defaults[blockType] ?? resolvedFallback;
        }
      }

      return resolvedFallback;
    },
    [],
    ...(editorId ? [{ id: editorId }] : []),
  );
}
